from datetime import date, timedelta


def _is_working_day(day, holidays):
    """True if `day` is Monday-Friday and not a holiday."""
    if day.weekday() >= 5:  # Saturday (5) or Sunday (6)
        return False
    return day not in holidays


def _normalize_holidays(holidays):
    """Return a frozenset view of holidays without mutating the input."""
    if holidays is None:
        return frozenset()
    return frozenset(holidays)


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int, not bool or any other type")

    holidays = _normalize_holidays(holidays)

    # days == 0
    if days == 0:
        if _is_working_day(start, holidays):
            return start
        # first working day after start
        step = 1
        day = start
        while True:
            day = day + timedelta(days=step)
            if _is_working_day(day, holidays):
                return day

    step = 1 if days > 0 else -1
    remaining = abs(days)
    day = start
    while remaining > 0:
        day = day + timedelta(days=step)
        if _is_working_day(day, holidays):
            remaining -= 1
    return day


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    holidays = _normalize_holidays(holidays)

    if first > last:
        return -count_workdays(last, first, holidays)

    count = 0
    day = first
    one_day = timedelta(days=1)
    while day <= last:
        if _is_working_day(day, holidays):
            count += 1
        day = day + one_day
    return count
